const hint=()=>P.note(`این صفحه <b>دادهٔ نمونه</b> است. برای دیدن منو و رسپی واقعی، در «انبار ← داشبورد کنترل» به داده وصل شوید. <a href="#/inventory/control">اتصال</a>`,'database');
const REAL={items:{render:itemsReal,mount:itemsMount},campaign:{render:campReal,mount:campMount},recipes:{render:recipesReal,mount:recipesMount},pricing:{render:pricingReal,mount:pricingMount},engineering:{render:engReal,mount:engMount},settings:{render:settingsReal,mount:settingsMount},
 channels:{render:null}};
for(const [id,v] of Object.entries(REAL)){const t=mod.tabs.find(x=>x.id===id);if(!t)continue;const r0=t.render,m0=t.mount,a0=t.actions;
 t.render=r=>IC.ready()?(v.render?v.render(r):P.note('قیمت و قاعدهٔ هر کانال فروش هنوز در دادهٔ رایو ثبت نمی‌شود؛ این صفحه نمونه است.','info')+r0(r)):hint()+r0(r);
 t.mount=(root,r)=>{if(IC.ready()&&v.render){v.mount&&v.mount(root,r)}else m0&&m0(root,r)};
 if(a0)t.actions=r=>IC.ready()&&v.render?(canWrite()?'':`<button class="btn btn-secondary" disabled title="${esc(whyLocked())}">${P.ic('lock')}فقط خواندنی</button>`):a0(r);}
mod.badge=()=>0; // items without a recipe: a one-time job in the recipe list, not a daily red counter (APP_REVIEW N-13)
window.MenuReal={metrics,sales,engData};
